// src/App.js
import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import AdminDashboard from './components/Admin/AdminDashboard';
import HomePage from './components/User/HomePage';
import CheckoutPage from './components/User/CheckoutPage';
import ThankYouPage from './components/User/ThankYouPage';
import { INITIAL_MENU, INITIAL_ORDERS, INITIAL_CHEFS } from './mockData';
import './App.css';

const generateInitialTables = () => {
  const generatedTables = [];
  const sizes = [2, 4, 6, 8];
  for (let i = 1; i <= 30; i++) {
    const randomSize = sizes[Math.floor(Math.random() * sizes.length)];
    generatedTables.push({ id:`t${i}`, number:i, name:null, size:randomSize, status:'Available' });
  }
  return generatedTables;
};

// persistence helpers
const loadState = (k,f)=>{ try{const r=localStorage.getItem(k); return r?JSON.parse(r):f;}catch{return f;} };
const saveState = (k,v)=>{ try{localStorage.setItem(k,JSON.stringify(v));}catch{} };

function App() {
  const [menuItems, setMenuItems] = useState(()=>loadState('menuItems', INITIAL_MENU));
  const [tables, setTables] = useState(()=>loadState('tables', generateInitialTables()));
  const [orders, setOrders] = useState(()=>loadState('orders', INITIAL_ORDERS));
  const [cart, setCart] = useState(()=>loadState('cart', []));
  const [chefs, setChefs] = useState(()=>loadState('chefs', INITIAL_CHEFS));

  const [isModalOpen, setIsModalOpen] = useState(true);
  const [userDetails, setUserDetails] = useState(null);

  useEffect(()=>saveState('menuItems', menuItems),[menuItems]);
  useEffect(()=>saveState('tables', tables),[tables]);
  useEffect(()=>saveState('orders', orders),[orders]);
  useEffect(()=>saveState('cart', cart),[cart]);
  useEffect(()=>saveState('chefs', chefs),[chefs]);

  const addProduct = (newProduct) => {
    const productToAdd = {
      id:`p${Date.now()}`,
      ...newProduct,
      description:newProduct.description || 'No description.',
      averagePreparationTime:newProduct.averagePreparationTime || 10,
      stock:newProduct.stock || 'In Stock',
    };
    setMenuItems(prev=>[...prev, productToAdd]);
  };

  const updateOrderStatus = (orderId, newStatus) => {
    setOrders(prev=>prev.map(o=>o.id===orderId?{...o,status:newStatus}:o));
    if (newStatus === 'done') {
      const orderToComplete = orders.find(o=>o.id===orderId);
      if (orderToComplete && orderToComplete.type==='Dine In' && orderToComplete.table.startsWith('Table-')) {
        const tableNum = parseInt(orderToComplete.table.replace('Table-',''),10);
        setTables(prev=>prev.map(t=>t.number===tableNum?{...t,status:'Available'}:t));
      }
      setChefs(prev=>prev.map(c=>c.orders>0?{...c,orders:c.orders-1}:c));
    }
  };

  const deleteTable = (tableId) => {
    setTables(prev=>{
      const filtered = prev.filter(t=>t.id!==tableId);
      return filtered.map((t,i)=>({...t,number:i+1}));
    });
  };

  const addTable = (tableData) => {
    setTables(prev=>{
      const n = prev.length+1;
      return [...prev, {id:`t${n}`, number:n, name:tableData.name||null, size:parseInt(tableData.size,10), status:'Available'}];
    });
  };

  const assignOrderToChef = () => {
    setChefs(prev=>{
      if (!prev.length) return prev;
      const minChef = prev.reduce((m,c)=>c.orders<m.orders?c:m, prev[0]);
      return prev.map(c=>c.id===minChef.id?{...c,orders:c.orders+1}:c);
    });
  };

  const addToCart = (item) => {
    setCart(prev=>{
      const ex = prev.find(i=>i.id===item.id);
      if (ex) {
        const q = item.quantity!==undefined? item.quantity : ex.quantity+1;
        if (q<=0) return prev.filter(i=>i.id!==item.id);
        return prev.map(i=>i.id===item.id?{...i,quantity:q}:i);
      }
      return [...prev, {...item, quantity:1}];
    });
  };
  const updateCart = (itemId, quantity) => {
    if (quantity<=0) setCart(prev=>prev.filter(i=>i.id!==itemId));
    else setCart(prev=>prev.map(i=>i.id===itemId?{...i,quantity}:i));
  };

  const placeOrder = (orderDetails) => {
    const newId = orders.length + 1;
    const isDineIn = orderDetails.type === 'Dine In';
    let tableIdentifier = 'Takeaway';
    let assignedTableNumber = null;

    if (isDineIn) {
      if (orderDetails.tableNum && orderDetails.tableNum !== 'N/A') {
        assignedTableNumber = parseInt(orderDetails.tableNum,10);
        tableIdentifier = `Table-${assignedTableNumber}`;
        setTables(prev=>prev.map(t=>t.number===assignedTableNumber?{...t,status:'Reserved'}:t));
      } else {
        tableIdentifier = 'Dine In';
      }
    }

    const durationMinutes = 15; // you can make this dynamic per item later

    const newOrder = {
      id: newId,
      items: cart,
      status: 'processing',
      time: new Date().toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}),
      table: tableIdentifier,
      itemCount: cart.reduce((a,i)=>a+i.quantity,0),
      // timing fields for live countdown:
      durationMinutes,
      startedAt: Date.now(),
      // keep your original fields too:
      ...orderDetails,
    };

    setOrders(prev=>[newOrder, ...prev]);
    setCart([]);
    assignOrderToChef();
  };

  const handleDetailsSubmit = (details) => {
    setUserDetails(details);
    setIsModalOpen(false);
  };

  return (
    <Router>
      <Routes>
        <Route path="/" element={
          <HomePage
            menu={menuItems}
            cart={cart}
            addToCart={addToCart}
            isModalOpen={isModalOpen}
            onDetailsSubmit={handleDetailsSubmit}
          />
        }/>
        <Route path="/checkout" element={
          <CheckoutPage
            cart={cart}
            updateCart={updateCart}
            placeOrder={placeOrder}
            tables={tables}
            userDetails={userDetails}
          />
        }/>
        <Route path="/thankyou" element={<ThankYouPage/>}/>
        <Route path="/admin" element={
          <AdminDashboard
            orders={orders}
            tables={tables}
            menuItems={menuItems}
            chefs={chefs}
            updateOrderStatus={updateOrderStatus}
            deleteTable={deleteTable}
            addTable={addTable}
            addProduct={addProduct}
          />
        }/>
        <Route path="*" element={<Navigate to="/" />}/>
      </Routes>
    </Router>
  );
}

export default App;
